"""
IterResearch核心数据模型模块

定义研究过程中使用的所有数据结构，包括研究状态、报告、动作等
遵循论文中定义的Think-Report-Action三元结构
"""

from enum import Enum
from typing import Any, Dict, List, Optional, Union
from datetime import datetime
from pydantic import BaseModel, Field, validator


class ActionType(str, Enum):
    """动作类型枚举"""
    TOOL_CALL = "tool_call"
    FINAL_ANSWER = "final_answer"


class ToolType(str, Enum):
    """工具类型枚举"""
    SEARCH = "search"
    SCHOLAR = "scholar"
    VISIT = "visit"
    PYTHON = "python"


class ResearchStatus(str, Enum):
    """研究状态枚举"""
    INITIALIZING = "initializing"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"
    FAILED = "failed"


class ToolCall(BaseModel):
    """工具调用数据模型"""
    tool_type: ToolType = Field(..., description="工具类型")
    parameters: Dict[str, Any] = Field(default_factory=dict, description="工具参数")

    class Config:
        json_encoders = {
            ToolType: lambda v: v.value
        }


class ToolResponse(BaseModel):
    """工具响应数据模型"""
    tool_type: ToolType = Field(..., description="工具类型")
    success: bool = Field(..., description="执行是否成功")
    result: Any = Field(..., description="执行结果")
    error_message: Optional[str] = Field(None, description="错误信息")
    execution_time: float = Field(..., description="执行时间(秒)")
    metadata: Dict[str, Any] = Field(default_factory=dict, description="额外元数据")

    class Config:
        json_encoders = {
            ToolType: lambda v: v.value
        }


class Action(BaseModel):
    """研究动作数据模型 - 可以是工具调用或最终答案"""
    action_type: ActionType = Field(..., description="动作类型")
    tool_call: Optional[ToolCall] = Field(None, description="工具调用(当action_type为tool_call时)")
    final_answer: Optional[str] = Field(None, description="最终答案(当action_type为final_answer时)")

    @validator('tool_call', always=True)
    def validate_tool_call(cls, v, values):
        """验证工具调用字段"""
        if values.get('action_type') == ActionType.TOOL_CALL and v is None:
            raise ValueError("当action_type为tool_call时，必须提供tool_call")
        return v

    @validator('final_answer', always=True)
    def validate_final_answer(cls, v, values):
        """验证最终答案字段"""
        if values.get('action_type') == ActionType.FINAL_ANSWER and not v:
            raise ValueError("当action_type为final_answer时，必须提供final_answer")
        return v

    class Config:
        json_encoders = {
            ActionType: lambda v: v.value
        }


class ThinkComponent(BaseModel):
    """思考组件 - 代理的认知草稿"""
    content: str = Field(..., description="思考内容")
    reasoning_steps: List[str] = Field(default_factory=list, description="推理步骤")
    current_analysis: str = Field(..., description="当前状态分析")
    next_action_plan: str = Field(..., description="下一步行动计划")

    def __str__(self) -> str:
        return f"Think: {self.content[:100]}..."


class ReportComponent(BaseModel):
    """报告组件 - 代理的演进中央记忆"""
    summary: str = Field(..., description="研究摘要")
    key_findings: List[str] = Field(default_factory=list, description="关键发现")
    evidence_sources: List[str] = Field(default_factory=list, description="证据来源")
    progress_status: str = Field(..., description="进展状态")
    next_research_directions: List[str] = Field(default_factory=list, description="下一步研究方向")
    confidence_level: float = Field(default=0.5, ge=0, le=1, description="置信度水平")

    def update_with_new_findings(self, new_findings: List[str], sources: List[str]) -> None:
        """使用新发现更新报告"""
        self.key_findings.extend(new_findings)
        self.evidence_sources.extend(sources)

    def __str__(self) -> str:
        return f"Report: {self.summary[:100]}... (Confidence: {self.confidence_level:.2f})"


class ResearchRound(BaseModel):
    """单轮研究数据模型"""
    round_number: int = Field(..., description="轮次编号")
    think: ThinkComponent = Field(..., description="思考组件")
    report: ReportComponent = Field(..., description="报告组件")
    action: Action = Field(..., description="动作组件")
    tool_response: Optional[ToolResponse] = Field(None, description="工具响应(如果有)")
    timestamp: datetime = Field(default_factory=datetime.now, description="时间戳")

    class Config:
        json_encoders = {
            datetime: lambda v: v.isoformat()
        }


class ResearchState(BaseModel):
    """研究状态数据模型 - MDP中的状态表示"""
    question: str = Field(..., description="原始研究问题")
    current_report: Optional[ReportComponent] = Field(None, description="当前报告")
    last_action: Optional[Action] = Field(None, description="上一个动作")
    last_tool_response: Optional[ToolResponse] = Field(None, description="上一个工具响应")
    round_number: int = Field(default=0, description="当前轮次编号")

    def is_initial_state(self) -> bool:
        """检查是否为初始状态"""
        return self.round_number == 0 and self.current_report is None

    def advance_round(self, new_report: ReportComponent, action: Action, 
                     tool_response: Optional[ToolResponse] = None) -> 'ResearchState':
        """推进到下一轮状态"""
        return ResearchState(
            question=self.question,
            current_report=new_report,
            last_action=action,
            last_tool_response=tool_response,
            round_number=self.round_number + 1
        )


class ResearchSession(BaseModel):
    """完整研究会话数据模型"""
    session_id: str = Field(..., description="会话ID")
    initial_question: str = Field(..., description="初始研究问题")
    rounds: List[ResearchRound] = Field(default_factory=list, description="研究轮次列表")
    final_answer: Optional[str] = Field(None, description="最终答案")
    status: ResearchStatus = Field(default=ResearchStatus.INITIALIZING, description="研究状态")
    start_time: datetime = Field(default_factory=datetime.now, description="开始时间")
    end_time: Optional[datetime] = Field(None, description="结束时间")
    total_rounds: int = Field(default=0, description="总轮次数")

    def add_round(self, research_round: ResearchRound) -> None:
        """添加新的研究轮次"""
        self.rounds.append(research_round)
        self.total_rounds = len(self.rounds)

    def complete_session(self, final_answer: str) -> None:
        """完成研究会话"""
        self.final_answer = final_answer
        self.status = ResearchStatus.COMPLETED
        self.end_time = datetime.now()

    def get_current_state(self) -> ResearchState:
        """获取当前研究状态"""
        if not self.rounds:
            return ResearchState(question=self.initial_question)

        last_round = self.rounds[-1]
        return ResearchState(
            question=self.initial_question,
            current_report=last_round.report,
            last_action=last_round.action,
            last_tool_response=last_round.tool_response,
            round_number=len(self.rounds)
        )

    class Config:
        json_encoders = {
            datetime: lambda v: v.isoformat(),
            ResearchStatus: lambda v: v.value
        }


class ParallelResearchResult(BaseModel):
    """并行研究结果数据模型"""
    agent_id: str = Field(..., description="代理ID")
    session: ResearchSession = Field(..., description="研究会话")
    final_report: ReportComponent = Field(..., description="最终报告")
    final_answer: str = Field(..., description="最终答案")
    success: bool = Field(..., description="是否成功")
    error_message: Optional[str] = Field(None, description="错误信息")

    class Config:
        json_encoders = {
            datetime: lambda v: v.isoformat()
        }


class SynthesisResult(BaseModel):
    """综合结果数据模型"""
    parallel_results: List[ParallelResearchResult] = Field(..., description="并行研究结果列表")
    synthesized_answer: str = Field(..., description="综合答案")
    confidence_score: float = Field(..., ge=0, le=1, description="置信度分数")
    synthesis_reasoning: str = Field(..., description="综合推理过程")
    timestamp: datetime = Field(default_factory=datetime.now, description="时间戳")

    class Config:
        json_encoders = {
            datetime: lambda v: v.isoformat()
        }
